BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
LOCK TABLE public."customers",public."customer_groups",public."sales_territories",public."customer_documents",public."customer_follow_ups",public."suppliers",public."expenses",public."purchase_orders",public."quotations",public."sales_orders",public."invoices",public."promotions",public."stock_count_sessions",public."system_settings",public.products,public.product_categories,public.dosage_forms,public.drugs,public.warehouses IN SHARE ROW EXCLUSIVE MODE;
DO $products$ DECLARE entry jsonb; cat uuid; form uuid; drug uuid; warehouse uuid; seq integer; BEGIN
 SELECT id INTO cat FROM public.product_categories WHERE code='MED'; SELECT id INTO warehouse FROM public.warehouses WHERE code='MAIN'; IF warehouse IS NULL THEN SELECT id INTO warehouse FROM public.warehouses ORDER BY code LIMIT 1; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements('[["พาราเซตามอล","พาราเซตามอล 500 มก.","TAB","กล่อง","120.00"],["อะม็อกซีซิลลิน","อะม็อกซีซิลลิน 250 มก.","CAP","กล่อง","175.00"],["Amlodipine","แอมโลดิพีนชนิดเม็ด","TAB","กล่อง","180.00"],["Amoxicillin","อะม็อกซีซิลลินชนิดเม็ด","TAB","กล่อง","240.00"],["Atorvastatin","อะทอร์วาสแตตินชนิดเม็ด","TAB","กล่อง","320.00"],["Calcium carbonate","แคลเซียมคาร์บอเนตชนิดเม็ด","TAB","ขวด","95.00"],["Cetirizine","เซทิริซีนชนิดเม็ด","TAB","กล่อง","85.00"],["Ibuprofen","ไอบูโพรเฟนชนิดเม็ด","TAB","กล่อง","110.00"],["Loratadine","ลอราทาดีนชนิดเม็ด","TAB","กล่อง","105.00"],["Losartan","โลซาร์แทนชนิดเม็ด","TAB","กล่อง","230.00"],["Metformin","เมตฟอร์มินชนิดเม็ด","TAB","กล่อง","140.00"],["Omeprazole","โอเมพราโซลชนิดเม็ด","TAB","กล่อง","165.00"],["Paracetamol","พาราเซตามอลชนิดเม็ด","TAB","กล่อง","115.00"],["Normal saline","น้ำเกลือสำหรับล้างแผล 100 มล.","SOL","ขวด","32.00"],["Oral rehydration salts","ผงเกลือแร่สำหรับละลายน้ำ","PWD","กล่อง","75.00"]]'::jsonb) LOOP
 EXIT WHEN (SELECT count(*) FROM public.products WHERE deleted_at IS NULL)>=15;
 CONTINUE WHEN EXISTS(SELECT 1 FROM public.products WHERE name=entry->>1);
 SELECT id INTO form FROM public.dosage_forms WHERE code=entry->>2; SELECT id INTO drug FROM public.drugs WHERE name=entry->>0;
 SELECT coalesce(max(sequence),0)+1 INTO seq FROM public.products WHERE category_id=cat AND dosage_form_id=form;
 IF seq>9999 THEN RAISE EXCEPTION 'Product sequence exhausted'; END IF;
 END LOOP; END $products$;
COMMIT;
SELECT (SELECT count(*)::int FROM public."customers" WHERE deleted_at IS NULL) AS "customers",(SELECT count(*)::int FROM public."customer_groups" WHERE deleted_at IS NULL) AS "customer-groups",(SELECT count(*)::int FROM public."sales_territories" WHERE deleted_at IS NULL) AS "sales-territories",(SELECT count(*)::int FROM public."customer_documents" WHERE deleted_at IS NULL) AS "customer-documents",(SELECT count(*)::int FROM public."customer_follow_ups" WHERE deleted_at IS NULL) AS "customer-follow-ups",(SELECT count(*)::int FROM public."suppliers" WHERE deleted_at IS NULL) AS "suppliers",(SELECT count(*)::int FROM public."expenses" WHERE deleted_at IS NULL) AS "expenses",(SELECT count(*)::int FROM public."purchase_orders" WHERE deleted_at IS NULL) AS "purchases",(SELECT count(*)::int FROM public."quotations" WHERE deleted_at IS NULL) AS "quotes",(SELECT count(*)::int FROM public."sales_orders" WHERE deleted_at IS NULL) AS "orders",(SELECT count(*)::int FROM public."invoices" WHERE deleted_at IS NULL) AS "billing",(SELECT count(*)::int FROM public."promotions" WHERE deleted_at IS NULL) AS "promotions",(SELECT count(*)::int FROM public."stock_count_sessions" WHERE deleted_at IS NULL) AS "stock-counts",(SELECT count(*)::int FROM public."system_settings" WHERE deleted_at IS NULL) AS "settings",(SELECT count(*)::int FROM public.products WHERE deleted_at IS NULL) products;
