INSERT INTO public.product_categories(id,code,name) SELECT gen_random_uuid(),v.code,v.name FROM (VALUES ('MED','ยาแผนปัจจุบัน'),('HER','ยาสมุนไพร/ยาแผนไทย'),('SUP','เวชภัณฑ์'),('VIT','วิตามิน'),('NUT','ผลิตภัณฑ์โภชนาการ'),('COS','ผลิตภัณฑ์ดูแลผิว'),('DEN','ทันตกรรม'),('LAB','อุปกรณ์ห้องปฏิบัติการ'),('EQP','เครื่องมือแพทย์'),('SAN','ผลิตภัณฑ์ทำความสะอาด'),('REH','อุปกรณ์ฟื้นฟู'),('PED','ผลิตภัณฑ์สำหรับเด็ก'),('VET','เวชภัณฑ์สัตว์'),('WND','อุปกรณ์ดูแลแผล'),('GEN','ผลิตภัณฑ์ทั่วไป')) v(code,name) WHERE NOT EXISTS(SELECT 1 FROM public.product_categories t WHERE t.code=v.code OR t.name=v.name) ON CONFLICT DO NOTHING;
INSERT INTO public.dosage_forms(id,code,name) SELECT gen_random_uuid(),v.code,v.name FROM (VALUES ('TAB','ยาเม็ด'),('CAP','แคปซูล'),('SYR','น้ำเชื่อม'),('INJ','ยาฉีด'),('CRM','ครีม'),('GEL','เจล'),('OIN','ขี้ผึ้ง'),('DRP','ยาหยด'),('SPR','สเปรย์'),('PWD','ผง'),('SOL','สารละลาย'),('SUS','ยาน้ำแขวนตะกอน'),('SUP','ยาเหน็บ'),('PAD','แผ่น'),('DEV','อุปกรณ์')) v(code,name) WHERE NOT EXISTS(SELECT 1 FROM public.dosage_forms t WHERE t.code=v.code OR t.name=v.name) ON CONFLICT DO NOTHING;
INSERT INTO public.warehouses(id,code,name) SELECT gen_random_uuid(),v.code,v.name FROM (VALUES ('WH-INIT-01','คลังจัดเก็บเวชภัณฑ์ส่วนกลาง'),('WH-INIT-02','คลังพักสินค้ารอจัดส่ง'),('WH-INIT-03','คลังสินค้าฝั่งธนบุรี'),('WH-INIT-04','คลังสินค้าปริมณฑล'),('WH-INIT-05','คลังสินค้าภาคตะวันออก'),('WH-INIT-06','คลังสินค้าภาคเหนือ'),('WH-INIT-07','คลังสินค้าภาคอีสาน'),('WH-INIT-08','คลังสินค้าภาคใต้'),('WH-INIT-09','คลังวัสดุบรรจุภัณฑ์'),('WH-INIT-10','คลังอุปกรณ์ดูแลแผล'),('WH-INIT-11','คลังสินค้ารอตรวจเอกสาร'),('WH-INIT-12','คลังสินค้ารับคืนรอตรวจสอบ'),('WH-INIT-13','คลังสินค้าจัดกิจกรรม'),('WH-INIT-14','คลังอุปกรณ์สำนักงาน'),('WH-INIT-15','คลังพักสินค้ารับเข้า')) v(code,name) WHERE NOT EXISTS(SELECT 1 FROM public.warehouses t WHERE t.code=v.code OR t.name=v.name) ON CONFLICT DO NOTHING;
INSERT INTO public.drugs(id,name) VALUES (gen_random_uuid(),'พาราเซตามอล'),(gen_random_uuid(),'อะม็อกซีซิลลิน'),(gen_random_uuid(),'Amlodipine'),(gen_random_uuid(),'Amoxicillin'),(gen_random_uuid(),'Atorvastatin'),(gen_random_uuid(),'Calcium carbonate'),(gen_random_uuid(),'Cetirizine'),(gen_random_uuid(),'Ibuprofen'),(gen_random_uuid(),'Loratadine'),(gen_random_uuid(),'Losartan'),(gen_random_uuid(),'Metformin'),(gen_random_uuid(),'Omeprazole'),(gen_random_uuid(),'Paracetamol'),(gen_random_uuid(),'Normal saline'),(gen_random_uuid(),'Oral rehydration salts'),(gen_random_uuid(),'Vitamin C'),(gen_random_uuid(),'Zinc sulfate') ON CONFLICT(name) DO NOTHING;
INSERT INTO public."customer_groups"(id,"code","name","status","category","description","owner","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",v."category",v."description",v."owner",v."notes" FROM (VALUES (0,'GRP-INIT-001','ร้านยาอิสระภาคกลาง','ใช้งานอยู่','ร้านยา','กลุ่มลูกค้าสำหรับประสานงาน กรุงเทพฝั่งธนบุรี','กิตติพงศ์ วัฒนภักดี','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(1,'GRP-INIT-002','คลินิกเวชกรรมเอกชน','ใช้งานอยู่','คลินิก','กลุ่มลูกค้าสำหรับประสานงาน นนทบุรีและบางบัวทอง','ณัฐชา สุขเกษม','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(2,'GRP-INIT-003','ผู้จำหน่ายเวชภัณฑ์','ใช้งานอยู่','ผู้จำหน่าย','กลุ่มลูกค้าสำหรับประสานงาน ปทุมธานีและรังสิต','พิมพ์ชนก ธารารัตน์','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(3,'GRP-INIT-004','โรงพยาบาลเอกชนภาคกลาง','ใช้งานอยู่','โรงพยาบาล','กลุ่มลูกค้าสำหรับประสานงาน นครปฐมและสามพราน','ธนกร ศิริพงษ์','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(4,'GRP-INIT-005','ร้านยาชุมชนภาคตะวันตก','ใช้งานอยู่','ร้านยา','กลุ่มลูกค้าสำหรับประสานงาน ราชบุรีและบ้านโป่ง','สุรีย์พร จันทร์ดี','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(5,'GRP-INIT-006','คลินิกเครือข่ายปริมณฑล','ใช้งานอยู่','คลินิก','กลุ่มลูกค้าสำหรับประสานงาน สมุทรปราการและบางพลี','กิตติพงศ์ วัฒนภักดี','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(6,'GRP-INIT-007','ศูนย์ดูแลสุขภาพภาคตะวันออก','ใช้งานอยู่','ศูนย์สุขภาพ','กลุ่มลูกค้าสำหรับประสานงาน ชลบุรีและศรีราชา','ณัฐชา สุขเกษม','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(7,'GRP-INIT-008','ร้านยาภาคตะวันออก','ใช้งานอยู่','ร้านยา','กลุ่มลูกค้าสำหรับประสานงาน ระยองและบ้านฉาง','พิมพ์ชนก ธารารัตน์','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(8,'GRP-INIT-009','คลินิกเวชกรรมภาคเหนือ','ใช้งานอยู่','คลินิก','กลุ่มลูกค้าสำหรับประสานงาน เชียงใหม่และลำพูน','ธนกร ศิริพงษ์','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(9,'GRP-INIT-010','ผู้จำหน่ายภาคเหนือ','ใช้งานอยู่','ผู้จำหน่าย','กลุ่มลูกค้าสำหรับประสานงาน เชียงรายและพะเยา','สุรีย์พร จันทร์ดี','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(10,'GRP-INIT-011','โรงพยาบาลภาคตะวันออกเฉียงเหนือ','ใช้งานอยู่','โรงพยาบาล','กลุ่มลูกค้าสำหรับประสานงาน ขอนแก่นและมหาสารคาม','กิตติพงศ์ วัฒนภักดี','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(11,'GRP-INIT-012','ร้านยาชุมชนภาคอีสาน','ใช้งานอยู่','ร้านยา','กลุ่มลูกค้าสำหรับประสานงาน นครราชสีมาและปากช่อง','ณัฐชา สุขเกษม','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(12,'GRP-INIT-013','คลินิกเวชกรรมภาคอีสาน','ใช้งานอยู่','คลินิก','กลุ่มลูกค้าสำหรับประสานงาน อุบลราชธานีและศรีสะเกษ','พิมพ์ชนก ธารารัตน์','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(13,'GRP-INIT-014','ศูนย์สุขภาพภาคใต้','ใช้งานอยู่','ศูนย์สุขภาพ','กลุ่มลูกค้าสำหรับประสานงาน สงขลาและหาดใหญ่','ธนกร ศิริพงษ์','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย'),(14,'GRP-INIT-015','ร้านยาชุมชนภาคใต้','ใช้งานอยู่','ร้านยา','กลุ่มลูกค้าสำหรับประสานงาน สุราษฎร์ธานีและชุมพร','สุรีย์พร จันทร์ดี','ใช้จัดกลุ่มรายชื่อและติดตามงานขาย')) v(position,"code","name","status","category","description","owner","notes") WHERE NOT EXISTS(SELECT 1 FROM public."customer_groups" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."customer_groups" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
INSERT INTO public."sales_territories"(id,"code","name","status","area","owner","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",v."area",v."owner",v."notes" FROM (VALUES (0,'TER-INIT-001','กรุงเทพฝั่งธนบุรี','ใช้งานอยู่','กรุงเทพฝั่งธนบุรี','กิตติพงศ์ วัฒนภักดี','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(1,'TER-INIT-002','นนทบุรีและบางบัวทอง','ใช้งานอยู่','นนทบุรีและบางบัวทอง','ณัฐชา สุขเกษม','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(2,'TER-INIT-003','ปทุมธานีและรังสิต','ใช้งานอยู่','ปทุมธานีและรังสิต','พิมพ์ชนก ธารารัตน์','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(3,'TER-INIT-004','นครปฐมและสามพราน','ใช้งานอยู่','นครปฐมและสามพราน','ธนกร ศิริพงษ์','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(4,'TER-INIT-005','ราชบุรีและบ้านโป่ง','ใช้งานอยู่','ราชบุรีและบ้านโป่ง','สุรีย์พร จันทร์ดี','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(5,'TER-INIT-006','สมุทรปราการและบางพลี','ใช้งานอยู่','สมุทรปราการและบางพลี','กิตติพงศ์ วัฒนภักดี','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(6,'TER-INIT-007','ชลบุรีและศรีราชา','ใช้งานอยู่','ชลบุรีและศรีราชา','ณัฐชา สุขเกษม','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(7,'TER-INIT-008','ระยองและบ้านฉาง','ใช้งานอยู่','ระยองและบ้านฉาง','พิมพ์ชนก ธารารัตน์','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(8,'TER-INIT-009','เชียงใหม่และลำพูน','ใช้งานอยู่','เชียงใหม่และลำพูน','ธนกร ศิริพงษ์','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(9,'TER-INIT-010','เชียงรายและพะเยา','ใช้งานอยู่','เชียงรายและพะเยา','สุรีย์พร จันทร์ดี','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(10,'TER-INIT-011','ขอนแก่นและมหาสารคาม','ใช้งานอยู่','ขอนแก่นและมหาสารคาม','กิตติพงศ์ วัฒนภักดี','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(11,'TER-INIT-012','นครราชสีมาและปากช่อง','ใช้งานอยู่','นครราชสีมาและปากช่อง','ณัฐชา สุขเกษม','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(12,'TER-INIT-013','อุบลราชธานีและศรีสะเกษ','ใช้งานอยู่','อุบลราชธานีและศรีสะเกษ','พิมพ์ชนก ธารารัตน์','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(13,'TER-INIT-014','สงขลาและหาดใหญ่','ใช้งานอยู่','สงขลาและหาดใหญ่','ธนกร ศิริพงษ์','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง'),(14,'TER-INIT-015','สุราษฎร์ธานีและชุมพร','ใช้งานอยู่','สุราษฎร์ธานีและชุมพร','สุรีย์พร จันทร์ดี','ประสานลูกค้าในพื้นที่และนัดหมายก่อนเดินทาง')) v(position,"code","name","status","area","owner","notes") WHERE NOT EXISTS(SELECT 1 FROM public."sales_territories" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."sales_territories" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
INSERT INTO public."suppliers"(id,"code","name","status","category","location","contact","payment_terms","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",v."category",v."location",v."contact",v."paymentTerms",v."notes" FROM (VALUES (0,'SUP-INIT-001','บริษัท ธาราเวชซัพพลาย จำกัด','ใช้งานอยู่','เภสัชภัณฑ์','กรุงเทพมหานคร','กิตติพงศ์ วัฒนภักดี · ฝ่ายประสานผู้ขาย','เครดิต 30 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(1,'SUP-INIT-002','บริษัท ร่มไทรเมดิคอล จำกัด','ใช้งานอยู่','เวชภัณฑ์','นนทบุรี','ณัฐชา สุขเกษม · ฝ่ายประสานผู้ขาย','ชำระก่อนรับสินค้า','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(2,'SUP-INIT-003','บริษัท พฤกษาเภสัชภัณฑ์ จำกัด','ใช้งานอยู่','วัสดุบรรจุภัณฑ์','ปทุมธานี','พิมพ์ชนก ธารารัตน์ · ฝ่ายประสานผู้ขาย','เครดิต 15 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(3,'SUP-INIT-004','บริษัท อรุณสุขเฮลท์แคร์ จำกัด','ใช้งานอยู่','อุปกรณ์คลินิก','นครปฐม','ธนกร ศิริพงษ์ · ฝ่ายประสานผู้ขาย','เครดิต 30 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(4,'SUP-INIT-005','บริษัท เมธาเวชโปรดักส์ จำกัด','ใช้งานอยู่','บริการขนส่ง','ราชบุรี','สุรีย์พร จันทร์ดี · ฝ่ายประสานผู้ขาย','ชำระก่อนรับสินค้า','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(5,'SUP-INIT-006','บริษัท ศรีธาราเมดิคอล จำกัด','ใช้งานอยู่','เภสัชภัณฑ์','สมุทรปราการ','กิตติพงศ์ วัฒนภักดี · ฝ่ายประสานผู้ขาย','เครดิต 15 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(6,'SUP-INIT-007','บริษัท พิมพ์ใจเวชภัณฑ์ จำกัด','ใช้งานอยู่','เวชภัณฑ์','ชลบุรี','ณัฐชา สุขเกษม · ฝ่ายประสานผู้ขาย','เครดิต 30 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(7,'SUP-INIT-008','บริษัท วรินทร์ซัพพลาย จำกัด','ใช้งานอยู่','วัสดุบรรจุภัณฑ์','ระยอง','พิมพ์ชนก ธารารัตน์ · ฝ่ายประสานผู้ขาย','ชำระก่อนรับสินค้า','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(8,'SUP-INIT-009','บริษัท สวนธาราบรรจุภัณฑ์ จำกัด','ใช้งานอยู่','อุปกรณ์คลินิก','เชียงใหม่','ธนกร ศิริพงษ์ · ฝ่ายประสานผู้ขาย','เครดิต 15 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(9,'SUP-INIT-010','บริษัท พราวสุขเมดิคอล จำกัด','ใช้งานอยู่','บริการขนส่ง','เชียงราย','สุรีย์พร จันทร์ดี · ฝ่ายประสานผู้ขาย','เครดิต 30 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(10,'SUP-INIT-011','บริษัท แสงธาราโปรดักส์ จำกัด','ใช้งานอยู่','เภสัชภัณฑ์','ขอนแก่น','กิตติพงศ์ วัฒนภักดี · ฝ่ายประสานผู้ขาย','ชำระก่อนรับสินค้า','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(11,'SUP-INIT-012','บริษัท ร่มโพธิ์เวชภัณฑ์ จำกัด','ใช้งานอยู่','เวชภัณฑ์','นครราชสีมา','ณัฐชา สุขเกษม · ฝ่ายประสานผู้ขาย','เครดิต 15 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(12,'SUP-INIT-013','บริษัท ธารารักษ์โลจิสติกส์ จำกัด','ใช้งานอยู่','วัสดุบรรจุภัณฑ์','อุบลราชธานี','พิมพ์ชนก ธารารัตน์ · ฝ่ายประสานผู้ขาย','เครดิต 30 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(13,'SUP-INIT-014','บริษัท บ้านสวนเฮลท์แคร์ จำกัด','ใช้งานอยู่','อุปกรณ์คลินิก','สงขลา','ธนกร ศิริพงษ์ · ฝ่ายประสานผู้ขาย','ชำระก่อนรับสินค้า','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ'),(14,'SUP-INIT-015','บริษัท ศรีพฤกษ์ซัพพลาย จำกัด','ใช้งานอยู่','บริการขนส่ง','สุราษฎร์ธานี','สุรีย์พร จันทร์ดี · ฝ่ายประสานผู้ขาย','เครดิต 15 วัน','ยืนยันรายการและกำหนดส่งสินค้ากับผู้ประสานงานก่อนจัดซื้อ')) v(position,"code","name","status","category","location","contact","paymentTerms","notes") WHERE NOT EXISTS(SELECT 1 FROM public."suppliers" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."suppliers" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
INSERT INTO public."customers"(id,"code","name","status","category","province","owner","payment_terms","group_id","territory_id","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",v."category",v."province",v."owner",v."paymentTerms",coalesce((SELECT id FROM public."customer_groups" WHERE code='GRP-INIT-'||lpad((v.position+1)::text,3,'0') AND deleted_at IS NULL),(SELECT id FROM public."customer_groups" WHERE deleted_at IS NULL ORDER BY code OFFSET (v.position%greatest(1,(SELECT count(*)::int FROM public."customer_groups" WHERE deleted_at IS NULL))) LIMIT 1)),coalesce((SELECT id FROM public."sales_territories" WHERE code='TER-INIT-'||lpad((v.position+1)::text,3,'0') AND deleted_at IS NULL),(SELECT id FROM public."sales_territories" WHERE deleted_at IS NULL ORDER BY code OFFSET (v.position%greatest(1,(SELECT count(*)::int FROM public."sales_territories" WHERE deleted_at IS NULL))) LIMIT 1)),v."notes" FROM (VALUES (0,'CUS-INIT-001','ร้านยาร่มโพธิ์เภสัช','ใช้งานอยู่','ร้านยา','กรุงเทพมหานคร','กิตติพงศ์ วัฒนภักดี','ชำระก่อนจัดส่ง','ประสานรายการและที่อยู่จัดส่งกับฝ่ายบริการก่อนยืนยันคำสั่งซื้อ'),(1,'CUS-INIT-002','คลินิกเวชกรรมธารารักษ์','ใช้งานอยู่','คลินิก','นนทบุรี','ณัฐชา สุขเกษม','เครดิต 15 วัน','ประสานรายการและที่อยู่จัดส่งกับฝ่ายบริการก่อนยืนยันคำสั่งซื้อ'),(2,'CUS-INIT-003','บริษัท สุขสบายเมดิคอล จำกัด','ใช้งานอยู่','ผู้จำหน่าย','ปทุมธานี','พิมพ์ชนก ธารารัตน์','เครดิต 30 วัน','ประสานรายการและที่อยู่จัดส่งกับฝ่ายบริการก่อนยืนยันคำสั่งซื้อ'),(3,'CUS-INIT-004','โรงพยาบาลสวนธารา','ใช้งานอยู่','โรงพยาบาล','นครปฐม','ธนกร ศิริพงษ์','ชำระก่อนจัดส่ง','ประสานรายการและที่อยู่จัดส่งกับฝ่ายบริการก่อนยืนยันคำสั่งซื้อ'),(4,'CUS-INIT-005','ร้านยาบ้านสวนสุขภาพ','ใช้งานอยู่','ร้านยา','ราชบุรี','สุรีย์พร จันทร์ดี','เครดิต 15 วัน','ประสานรายการและที่อยู่จัดส่งกับฝ่ายบริการก่อนยืนยันคำสั่งซื้อ'),(5,'CUS-INIT-006','คลินิกเวชกรรมพิมพ์ใจ','ใช้งานอยู่','คลินิก','สมุทรปราการ','กิตติพงศ์ วัฒนภักดี','เครดิต 30 วัน','ประสานรายการและที่อยู่จัดส่งกับฝ่ายบริการก่อนยืนยันคำสั่งซื้อ'),(