INSERT INTO public."customer_documents"(id,"code","name","status","customer_id","document_type","date_text","file_url","owner","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",coalesce((SELECT id FROM public."customers" WHERE code='CUS-INIT-'||lpad((v.position+1)::text,3,'0') AND deleted_at IS NULL),(SELECT id FROM public."customers" WHERE deleted_at IS NULL ORDER BY code OFFSET (v.position%greatest(1,(SELECT count(*)::int FROM public."customers" WHERE deleted_at IS NULL))) LIMIT 1)),v."documentType",v."dateText",v."fileUrl",v."owner",v."notes" FROM (VALUES (0,'DOC-INIT-001','หนังสือรับรองกิจการ — ร้านยาร่มโพธิ์เภสัช','ร่าง','หนังสือรับรองกิจการ','1 ตุลาคม 2569','','กิตติพงศ์ วัฒนภักดี','รวบรวมข้อมูล ร้านยาร่มโพธิ์เภสัช สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(1,'DOC-INIT-002','แบบข้อมูลเปิดบัญชี — คลินิกเวชกรรมธารารักษ์','ร่าง','แบบข้อมูลเปิดบัญชี','2 ตุลาคม 2569','','ณัฐชา สุขเกษม','รวบรวมข้อมูล คลินิกเวชกรรมธารารักษ์ สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(2,'DOC-INIT-003','เอกสารที่อยู่จัดส่ง — บริษัท สุขสบายเมดิคอล จำกัด','ร่าง','เอกสารที่อยู่จัดส่ง','3 ตุลาคม 2569','','พิมพ์ชนก ธารารัตน์','รวบรวมข้อมูล บริษัท สุขสบายเมดิคอล จำกัด สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(3,'DOC-INIT-004','หนังสือแต่งตั้งผู้ประสานงาน — โรงพยาบาลสวนธารา','ร่าง','หนังสือแต่งตั้งผู้ประสานงาน','4 ตุลาคม 2569','','ธนกร ศิริพงษ์','รวบรวมข้อมูล โรงพยาบาลสวนธารา สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(4,'DOC-INIT-005','เอกสารเงื่อนไขการซื้อ — ร้านยาบ้านสวนสุขภาพ','ร่าง','เอกสารเงื่อนไขการซื้อ','5 ตุลาคม 2569','','สุรีย์พร จันทร์ดี','รวบรวมข้อมูล ร้านยาบ้านสวนสุขภาพ สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(5,'DOC-INIT-006','หนังสือรับรองกิจการ — คลินิกเวชกรรมพิมพ์ใจ','ร่าง','หนังสือรับรองกิจการ','6 ตุลาคม 2569','','กิตติพงศ์ วัฒนภักดี','รวบรวมข้อมูล คลินิกเวชกรรมพิมพ์ใจ สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(6,'DOC-INIT-007','แบบข้อมูลเปิดบัญชี — ศูนย์ดูแลสุขภาพวรินทร์','ร่าง','แบบข้อมูลเปิดบัญชี','7 ตุลาคม 2569','','ณัฐชา สุขเกษม','รวบรวมข้อมูล ศูนย์ดูแลสุขภาพวรินทร์ สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(7,'DOC-INIT-008','เอกสารที่อยู่จัดส่ง — ร้านยาพฤกษาเภสัช','ร่าง','เอกสารที่อยู่จัดส่ง','8 ตุลาคม 2569','','พิมพ์ชนก ธารารัตน์','รวบรวมข้อมูล ร้านยาพฤกษาเภสัช สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(8,'DOC-INIT-009','หนังสือแต่งตั้งผู้ประสานงาน — คลินิกเวชกรรมเมธารักษ์','ร่าง','หนังสือแต่งตั้งผู้ประสานงาน','9 ตุลาคม 2569','','ธนกร ศิริพงษ์','รวบรวมข้อมูล คลินิกเวชกรรมเมธารักษ์ สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(9,'DOC-INIT-010','เอกสารเงื่อนไขการซื้อ — บริษัท ธารารักษ์ซัพพลาย จำกัด','ร่าง','เอกสารเงื่อนไขการซื้อ','10 ตุลาคม 2569','','สุรีย์พร จันทร์ดี','รวบรวมข้อมูล บริษัท ธารารักษ์ซัพพลาย จำกัด สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(10,'DOC-INIT-011','หนังสือรับรองกิจการ — โรงพยาบาลศรีพฤกษ์','ร่าง','หนังสือรับรองกิจการ','11 ตุลาคม 2569','','กิตติพงศ์ วัฒนภักดี','รวบรวมข้อมูล โรงพยาบาลศรีพฤกษ์ สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(11,'DOC-INIT-012','แบบข้อมูลเปิดบัญชี — ร้านยาชุมชนอรุณสุข','ร่าง','แบบข้อมูลเปิดบัญชี','12 ตุลาคม 2569','','ณัฐชา สุขเกษม','รวบรวมข้อมูล ร้านยาชุมชนอรุณสุข สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(12,'DOC-INIT-013','เอกสารที่อยู่จัดส่ง — คลินิกเวชกรรมพราวสุข','ร่าง','เอกสารที่อยู่จัดส่ง','13 ตุลาคม 2569','','พิมพ์ชนก ธารารัตน์','รวบรวมข้อมูล คลินิกเวชกรรมพราวสุข สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(13,'DOC-INIT-014','หนังสือแต่งตั้งผู้ประสานงาน — ศูนย์สุขภาพร่มไทร','ร่าง','หนังสือแต่งตั้งผู้ประสานงาน','14 ตุลาคม 2569','','ธนกร ศิริพงษ์','รวบรวมข้อมูล ศูนย์สุขภาพร่มไทร สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์'),(14,'DOC-INIT-015','เอกสารเงื่อนไขการซื้อ — ร้านยาแสงธาราเภสัช','ร่าง','เอกสารเงื่อนไขการซื้อ','15 ตุลาคม 2569','','สุรีย์พร จันทร์ดี','รวบรวมข้อมูล ร้านยาแสงธาราเภสัช สำหรับตรวจเอกสารก่อนยืนยันบัญชี; ยังไม่ได้แนบไฟล์')) v(position,"code","name","status","documentType","dateText","fileUrl","owner","notes") WHERE NOT EXISTS(SELECT 1 FROM public."customer_documents" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."customer_documents" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
INSERT INTO public."customer_follow_ups"(id,"code","name","status","customer_id","category","province","follow_up_text","owner","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",coalesce((SELECT id FROM public."customers" WHERE code='CUS-INIT-'||lpad((v.position+1)::text,3,'0') AND deleted_at IS NULL),(SELECT id FROM public."customers" WHERE deleted_at IS NULL ORDER BY code OFFSET (v.position%greatest(1,(SELECT count(*)::int FROM public."customers" WHERE deleted_at IS NULL))) LIMIT 1)),v."category",v."province",v."followUpText",v."owner",v."notes" FROM (VALUES (0,'FUP-INIT-001','นัดสรุปความต้องการเวชภัณฑ์ — ร้านยาร่มโพธิ์เภสัช','ร่าง','นัดหมาย','กรุงเทพมหานคร','ติดต่อ ร้านยาร่มโพธิ์เภสัช เพื่อยืนยันรายการที่ต้องการและนัดหมายรอบ 1 ตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','บันทึกผลการประสานงานครั้งถัดไปหลังได้รับคำตอบจากลูกค้า'),(1,'FUP-INIT-002','ติดตามรอบจัดซื้อ — คลินิกเวชกรรมธารารักษ์','ร่าง','ติดตามคำสั่งซื้อ','นนทบุรี','ติดต่อ คลินิกเวชกรรมธารารักษ์ เพื่อยืนยันรายการที่ต้องการและนัดหมายรอบ 2 ตุลาคม 2569','ณัฐชา สุขเกษม','บันทึกผลการประสานงานครั้งถัดไปหลังได้รับคำตอบจากลูกค้า'),(2,'FUP-INIT-003','ยืนยันข้อมูลจัดส่ง — บริษัท สุขสบายเมดิคอล จำกัด','ร่าง','ข้อมูลจัดส่ง','ปทุมธานี','ติดต่อ บริษัท สุขสบายเมดิคอล จำกัด เพื่อยืนยันรายการที่ต้องการและนัดหมายรอบ 3 ตุลาคม 2569','พิมพ์ชนก ธารารัตน์','บันทึกผลการประสานงานครั้งถัดไปหลังได้รับคำตอบจากลูกค้า'),(3,'FUP-INIT-004','ประสานเอกสารเปิดบัญชี — โรงพยาบาลสวนธารา','ร่าง','เอกสารลูกค้า','นครปฐม','ติดต่อ โรงพยาบาลสวนธารา เพื่อยืนยันรายการที่ต้องการและนัดหมายรอบ 4 ตุลาคม 2569','ธนกร ศิริพงษ์','บันทึกผลการประสานงานครั้งถัดไปหลังได้รับคำตอบจากลูกค้า'),(4,'FUP-INIT-005','สอบถามแผนจัดซื้อรอบเดือน — ร้านยาบ้านสวนสุขภาพ','ร่าง','แผนจัดซื้อ','ราชบุรี','ติดต่อ ร้านยาบ้านสวนสุขภาพ เพื่อยืนยันรายการที่ต้องการและนัดหมายรอบ 5 ตุลาคม 2569','สุรีย์พร จันทร์ดี','บันทึกผลการประสานงานครั้งถัดไปหลังได้รับคำตอบจากลูกค้า'),(5,'FUP-INIT-006','นัดสรุปความต้องการเวชภัณฑ์ — คลินิกเวชกรรมพิมพ์ใจ','ร่าง','นัดหมาย','สมุทรปราการ','ติดต่อ คลินิกเ