สานเอกสารเปิดบัญชี — ศูนย์สุขภาพร่มไทร','ร่าง','เอกสารลูกค้า','สงขลา','ติดต่อ ศูนย์สุขภาพร่มไทร เพื่อยืนยันรายการที่ต้องการและนัดหมายรอบ 14 ตุลาคม 2569','ธนกร ศิริพงษ์','บันทึกผลการประสานงานครั้งถัดไปหลังได้รับคำตอบจากลูกค้า'),(14,'FUP-INIT-015','สอบถามแผนจัดซื้อรอบเดือน — ร้านยาแสงธาราเภสัช','ร่าง','แผนจัดซื้อ','สุราษฎร์ธานี','ติดต่อ ร้านยาแสงธาราเภสัช เพื่อยืนยันรายการที่ต้องการและนัดหมายรอบ 15 ตุลาคม 2569','สุรีย์พร จันทร์ดี','บันทึกผลการประสานงานครั้งถัดไปหลังได้รับคำตอบจากลูกค้า')) v(position,"code","name","status","category","province","followUpText","owner","notes") WHERE NOT EXISTS(SELECT 1 FROM public."customer_follow_ups" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."customer_follow_ups" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
