INSERT INTO public."invoices"(id,"code","name","status","customer_id","due_text","owner","amount","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",coalesce((SELECT id FROM public."customers" WHERE code='CUS-INIT-'||lpad((v.position+1)::text,3,'0') AND deleted_at IS NULL),(SELECT id FROM public."customers" WHERE deleted_at IS NULL ORDER BY code OFFSET (v.position%greatest(1,(SELECT count(*)::int FROM public."customers" WHERE deleted_at IS NULL))) LIMIT 1)),v."dueText",v."owner",nullif(v."amount",'')::numeric,v."notes" FROM (VALUES (0,'INV-INIT-001','วางบิลรอบตุลาคม — ร้านยาร่มโพธิ์เภสัช','ร่าง','นัดตรวจเอกสาร 10 ตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','8900','ยอดหัวเอกสารสำหรับประสานงาน ไม่ใช่ยอดลูกหนี้สุทธิหรือรับชำระแล้ว'),(1,'INV-INIT-002','วางบิลรอบตุลาคม — คลินิกเวชกรรมธารารักษ์','ร่าง','นัดตรวจเอกสาร 11 ตุลาคม 2569','ณัฐชา สุขเกษม','10250','ยอดหัวเอกสารสำหรับประสานงาน ไม่ใช่ยอดลูกหนี้สุทธิหรือรับชำระแล้ว'),(2,'INV-INIT-003','วางบิลรอบตุลาคม — บริษัท สุขสบายเมดิคอล จำกัด','ร่าง','นัดตรวจเอกสาร 12 ตุลาคม 2569','พิมพ์ชนก ธารารัตน์','11600','ยอดหัวเอกสารสำหรับประสานงาน ไม่ใช่ยอดลูกหนี้สุทธิหรือรับชำระแล้ว'),(3,'INV-INIT-004','วางบิลรอบตุลาคม — โรงพยาบาลสวนธารา','ร่าง','นัดตรวจเอกสาร 13 ตุลาคม 2569','ธนกร ศิริพงษ์','12950','ยอดหัวเอกสารสำหรับประสานงาน ไม่ใช่ยอดลูกหนี้สุทธิหรือรับชำระแล้ว'),(4,'INV-INIT-005','วางบิลรอบตุลาคม — ร้านยาบ้านสวนสุขภาพ','ร่าง','นัดตรวจเอกสาร 14 ตุลาคม 2569','สุรีย์พร จันทร์ดี','14300','ยอดหัวเอกสารสำหรับประสานงาน ไม่ใช่ยอดลูกหนี้สุทธิหรือรับชำระแล้ว'),(5,'INV-INIT-006','วางบิลรอบตุลาคม — คลินิกเวชกรรมพิมพ์ใจ','ร่าง','นัดตรวจเอกสาร 15 ตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','15650','ยอดหัวเอกสารสำหรับประสานงาน ไม่ใช่ยอดลูกหนี้สุทธิหรือรับชำระแล้ว'),(6,'INV-INIT-007','วางบิลรอบตุลาคม — ศูนย์ดูแลสุขภาพวรินทร์','ร่าง','นัดตรวจเอกสาร 16 ตุลาคม 2569','ณัฐชา สุขเกษม','17000','ยอดหัวเอกสารสำหรับประสานงาน ไม่ใช่ยอดลูกหนี้สุทธิหรือรับชำระแล้ว'),(7,'INV-INIT-008','วางบิลรอบตุลาคม — ร้านยาพฤกษาเภสัช','ร่าง','นัดตรวจเอกสาร 17 ตุลาคม 2569','พิมพ์ชนก