INSERT INTO public."promotions"(id,"code","name","status","category","description","owner","conditions","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",v."category",v."description",v."owner",v."conditions",v."notes" FROM (VALUES (0,'PRM-INIT-001','ชุดดูแลแผลสำหรับคลินิก','ใช้งานอยู่','เวชภัณฑ์','แผนกิจกรรมประสานลูกค้า กรุงเทพฝั่งธนบุรี · ตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(1,'PRM-INIT-002','แคมเปญร้านยาประจำไตรมาส','ใช้งานอยู่','ร้านยา','แผนกิจกรรมประสานลูกค้า นนทบุรีและบางบัวทอง · ตุลาคม 2569','ณัฐชา สุขเกษม','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(2,'PRM-INIT-003','ชุดเปิดบัญชีลูกค้าคลินิก','ใช้งานอยู่','คลินิก','แผนกิจกรรมประสานลูกค้า ปทุมธานีและรังสิต · ตุลาคม 2569','พิมพ์ชนก ธารารัตน์','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(3,'PRM-INIT-004','กิจกรรมแนะนำเวชภัณฑ์ภาคกลาง','ใช้งานอยู่','กิจกรรมลูกค้า','แผนกิจกรรมประสานลูกค้า นครปฐมและสามพราน · ตุลาคม 2569','ธนกร ศิริพงษ์','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(4,'PRM-INIT-005','ชุดสินค้าเพื่อร้านยาชุมชน','ใช้งานอยู่','อุปกรณ์ดูแลสุขภาพ','แผนกิจกรรมประสานลูกค้า ราชบุรีและบ้านโป่ง · ตุลาคม 2569','สุรีย์พร จันทร์ดี','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(5,'PRM-INIT-006','แคมเปญอุปกรณ์ดูแลสุขภาพ','ใช้งานอยู่','เวชภัณฑ์','แผนกิจกรรมประสานลูกค้า สมุทรปราการและบางพลี · ตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(6,'PRM-INIT-007','ชุดเวชภัณฑ์คลินิกเครือข่าย','ใช้งานอยู่','ร้านยา','แผนกิจกรรมประสานลูกค้า ชลบุรีและศรีราชา · ตุลาคม 2569','ณัฐชา สุขเกษม','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(7,'PRM-INIT-008','กิจกรรมลูกค้าภาคตะวันออก','ใช้งานอยู่','คลินิก','แผนกิจกรรมประสานลูกค้า ระยองและบ้านฉาง · ตุลาคม 2569','พิมพ์ชนก ธารารัตน์','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(8,'PRM-INIT-009','ชุดอุปกรณ์สำนักงานคลินิก','ใช้งานอยู่','กิจกรรมลูกค้า','แผนกิจกรรมประสานลูกค้า เชียงใหม่และลำพูน · ตุลาคม 2569','ธนกร ศิริพงษ์','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(9,'PRM-INIT-010','แคมเปญลูกค้าภาคเหนือ','ใช้งานอยู่','อุปกรณ์ดูแลสุขภาพ','แผนกิจกรรมประสานลูกค้า เชียงรายและพะเยา · ตุลาคม 2569','สุรีย์พร จันทร์ดี','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(10,'PRM-INIT-011','ชุดเวชภัณฑ์โรงพยาบาล','ใช้งานอยู่','เวชภัณฑ์','แผนกิจกรรมประสานลูกค้า ขอนแก่นและมหาสารคาม · ตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(11,'PRM-INIT-012','กิจกรรมร้านยาภาคอีสาน','ใช้งานอยู่','ร้านยา','แผนกิจกรรมประสานลูกค้า นครราชสีมาและปากช่อง · ตุลาคม 2569','ณัฐชา สุขเกษม','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(12,'PRM-INIT-013','ชุดดูแลแผลชุมชน','ใช้งานอยู่','คลินิก','แผนกิจกรรมประสานลูกค้า อุบลราชธานีและศรีสะเกษ · ตุลาคม 2569','พิมพ์ชนก ธารารัตน์','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(13,'PRM-INIT-014','แคมเปญลูกค้าภาคใต้','ใช้งานอยู่','กิจกรรมลูกค้า','แผนกิจกรรมประสานลูกค้า สงขลาและหาดใหญ่ · ตุลาคม 2569','ธนกร ศิริพงษ์','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย'),(14,'PRM-INIT-015','กิจกรรมแนะนำสินค้าเดือนตุลาคม','ใช้งานอยู่','อุปกรณ์ดูแลสุขภาพ','แผนกิจกรรมประสานลูกค้า สุราษฎร์ธานีและชุมพร · ตุลาคม 2569','สุรีย์พร จันทร์ดี','ยืนยันรายการและเงื่อนไขกับฝ่ายบริการก่อนใช้งาน ไม่มีคำนวณส่วนลดอัตโนมัติ','รายละเอียดกิจกรรมสำหรับเตรียมเอกสารและนัดหมาย')) v(position,"code","name","status","category","description","owner","conditions","notes") WHERE NOT EXISTS(SELECT 1 FROM public."promotions" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."promotions" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
INSERT INTO public."stock_count_sessions"(id,"code","name","status","warehouse_id","description","owner","result_text","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",coalesce((SELECT id FROM public."warehouses" WHERE code='WH-INIT-'||lpad((v.position+1)::text,2,'0') AND true),(SELECT id FROM public."warehouses" WHERE true ORDER BY code OFFSET (v.position%greatest(1,(SELECT count(*)::int FROM public."warehouses" WHERE true))) LIMIT 1)),v."description",v."owner",v."resultText",v."notes" FROM (VALUES (0,'CNT-INIT-001','ตรวจนับพื้นที่จัดเก็บ — คลังจัดเก็บเวชภัณฑ์ส่วนกลาง','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังจัดเก็บเวชภัณฑ์ส่วนกลาง · รอบตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(1,'CNT-INIT-002','ตรวจนับพื้นที่จัดเก็บ — คลังพักสินค้ารอจัดส่ง','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังพักสินค้ารอจัดส่ง · รอบตุลาคม 2569','ณัฐชา สุขเกษม','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(2,'CNT-INIT-003','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้าฝั่งธนบุรี','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้าฝั่งธนบุรี · รอบตุลาคม 2569','พิมพ์ชนก ธารารัตน์','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(3,'CNT-INIT-004','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้าปริมณฑล','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้าปริมณฑล · รอบตุลาคม 2569','ธนกร ศิริพงษ์','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(4,'CNT-INIT-005','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้าภาคตะวันออก','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้าภาคตะวันออก · รอบตุลาคม 2569','สุรีย์พร จันทร์ดี','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(5,'CNT-INIT-006','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้าภาคเหนือ','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้าภาคเหนือ · รอบตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(6,'CNT-INIT-007','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้าภาคอีสาน','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้าภาคอีสาน · รอบตุลาคม 2569','ณัฐชา สุขเกษม','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(7,'CNT-INIT-008','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้าภาคใต้','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้าภาคใต้ · รอบตุลาคม 2569','พิมพ์ชนก ธารารัตน์','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(8,'CNT-INIT-009','ตรวจนับพื้นที่จัดเก็บ — คลังวัสดุบรรจุภัณฑ์','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังวัสดุบรรจุภัณฑ์ · รอบตุลาคม 2569','ธนกร ศิริพงษ์','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(9,'CNT-INIT-010','ตรวจนับพื้นที่จัดเก็บ — คลังอุปกรณ์ดูแลแผล','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังอุปกรณ์ดูแลแผล · รอบตุลาคม 2569','สุรีย์พร จันทร์ดี','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(10,'CNT-INIT-011','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้ารอตรวจเอกสาร','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้ารอตรวจเอกสาร · รอบตุลาคม 2569','กิตติพงศ์ วัฒนภักดี','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(11,'CNT-INIT-012','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้ารับคืนรอตรวจสอบ','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้ารับคืนรอตรวจสอบ · รอบตุลาคม 2569','ณัฐชา สุขเกษม','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(12,'CNT-INIT-013','ตรวจนับพื้นที่จัดเก็บ — คลังสินค้าจัดกิจกรรม','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังสินค้าจัดกิจกรรม · รอบตุลาคม 2569','พิมพ์ชนก ธารารัตน์','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(13,'CNT-INIT-014','ตรวจนับพื้นที่จัดเก็บ — คลังอุปกรณ์สำนักงาน','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังอุปกรณ์สำนักงาน · รอบตุลาคม 2569','ธนกร ศิริพงษ์','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger'),(14,'CNT-INIT-015','ตรวจนับพื้นที่จัดเก็บ — คลังพักสินค้ารับเข้า','ร่าง','จัดเตรียมใบบันทึกสำหรับพื้นที่ คลังพักสินค้ารับเข้า · รอบตุลาคม 2569','สุรีย์พร จันทร์ดี','รอผลตรวจนับจากผู้ตรวจนับภายนอกระบบ','ผู้ดูแลบันทึกผลจากเอกสารเท่านั้น ไม่มีปรับยอดหรือสร้าง Ledger')) v(position,"code","name","status","description","owner","resultText","notes") WHERE NOT EXISTS(SELECT 1 FROM public."stock_count_sessions" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."stock_count_sessions" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
INSERT INTO public."system_settings"(id,"code","name","status","category","description","owner","value","notes") SELECT gen_random_uuid(),v."code",v."name",v."status",v."category",v."description",v."owner",v."value",v."notes" FROM (VALUES (0,'SET-INIT-001','ชื่อองค์กรบนเอกสาร','ใช้งานอยู่','องค์กร','ชื่อที่ใช้อ้างอิงในข้อมูลเอกสาร','กิตติพงศ์ วัฒนภักดี','ZUUGROUP','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(1,'SET-INIT-002','เวลาฝ่ายบริการลูกค้า','ใช้งานอยู่','ติดต่อ','เวลาติดต่อฝ่ายบริการ','ณัฐชา สุขเกษม','จันทร์–ศุกร์ 09:00–18:00','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(2,'SET-INIT-003','ช่องทางติดต่อฝ่ายบริการ','ใช้งานอยู่','ติดต่อ','หน่วยงานรับเรื่องติดต่อ','พิมพ์ชนก ธารารัตน์','ฝ่ายบริการลูกค้า ZUUGROUP','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(3,'SET-INIT-004','หมายเหตุท้ายใบเสนอราคา','ใช้งานอยู่','เอกสาร','ข้อความอ้างอิงท้ายเอกสาร','ธนกร ศิริพงษ์','ยืนยันรายการก่อนจัดทำคำสั่งซื้อ','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(4,'SET-INIT-005','หมายเหตุท้ายใบสั่งซื้อ','ใช้งานอยู่','เอกสาร','ข้อความสำหรับงานจัดซื้อ','สุรีย์พร จันทร์ดี','ตรวจรายการกับผู้ขายก่อนยืนยัน','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(5,'SET-INIT-006','แนวทางจัดเก็บเอกสารลูกค้า','ใช้งานอยู่','เอกสาร','ข้อมูลอ้างอิงการจัดหมวดเอกสาร','กิตติพงศ์ วัฒนภักดี','จัดเก็บตามรหัสลูกค้า','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(6,'SET-INIT-007','พื้นที่ให้บริการส่วนกลาง','ใช้งานอยู่','การขาย','พื้นที่ประสานงานฝ่ายบริการ','ณัฐชา สุขเกษม','กรุงเทพมหานครและปริมณฑล','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(7,'SET-INIT-008','รอบรวบรวมเอกสารวางบิล','ใช้งานอยู่','การเงิน','รอบงานเอกสารเพื่ออ้างอิง','พิมพ์ชนก ธารารัตน์','สิ้นเดือน','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(8,'SET-INIT-009','เงื่อนไขชำระสำหรับลูกค้าใหม่','ใช้งานอยู่','การเงิน','ข้อความอ้างอิง ไม่ใช้คำนวณเครดิต','ธนกร ศิริพงษ์','ยืนยันเงื่อนไขก่อนสั่งซื้อ','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(9,'SET-INIT-010','จุดประสานงานรับสินค้า','ใช้งานอยู่','คลัง','หน่วยงานประสานการรับสินค้า','สุรีย์พร จันทร์ดี','ฝ่ายรับสินค้า','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(10,'SET-INIT-011','รูปแบบวันที่บนเอกสาร','ใช้งานอยู่','เอกสาร','รูปแบบการเขียนวันที่เพื่ออ้างอิง','กิตติพงศ์ วัฒนภักดี','วัน เดือน พ.ศ.','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(11,'SET-INIT-012','ภาษาสำหรับติดต่อคู่ค้า','ใช้งานอยู่','ติดต่อ','ภาษาหลักในการประสานงาน','ณัฐชา สุขเกษม','ภาษาไทย','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(12,'SET-INIT-013','ชื่อหน่วยงานจัดซื้อ','ใช้งานอยู่','องค์กร','หน่วยงานจัดซื้อ','พิมพ์ชนก ธารารัตน์','ฝ่ายจัดซื้อและประสานผู้ขาย','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(13,'SET-INIT-014','ชื่อหน่วยงานการเงิน','ใช้งานอยู่','องค์กร','หน่วยงานการเงิน','ธนกร ศิริพงษ์','ฝ่ายการเงินและเอกสารวางบิล','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ'),(14,'SET-INIT-015','แนวทางตรวจสอบเอกสารก่อนจัดส่ง','ใช้งานอยู่','เอกสาร','รายการตรวจเอกสารเพื่ออ้างอิง','สุรีย์พร จันทร์ดี','ตรวจชื่อ ที่อยู่ และรายการก่อนส่ง','ค่าที่จัดเก็บสำหรับอ้างอิง ไม่เพิ่มหรือเปลี่ยนกฎการทำงานของระบบ')) v(position,"code","name","status","category","description","owner","value","notes") WHERE NOT EXISTS(SELECT 1 FROM public."system_settings" existing WHERE existing.code=v.code OR existing.name=v.name) ORDER BY v.position LIMIT greatest(0,15-(SELECT count(*)::int FROM public."system_settings" WHERE deleted_at IS NULL)) ON CONFLICT(code) DO NOTHING;
 INSERT INTO public.products(id,code,sequence,name,category_id,dosage_form_id,drug_id,default_warehouse_id,unit,sale_price,status,is_sample,updated_at) VALUES(gen_random_uuid(),'MED-'||(entry->>2)||'-'||lpad(seq::text,4,'0'),seq,entry->>1,cat,form,drug,warehouse,entry->>3,(entry->>4)::numeric,'ACTIVE',false,now());
